using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using PlantaoPro.Api.Operation360.Productivity;
namespace PlantaoPro.Api.Controllers;
[ApiController,Authorize,Route("api/favoritos")]public sealed class FavoritosController:ControllerBase{private readonly IProductivityService s;public FavoritosController(IProductivityService s)=>this.s=s;[HttpGet]public async Task<IActionResult>Get(CancellationToken ct)=>Ok(await s.FavoritesAsync(ct));[HttpPost]public async Task<IActionResult>Post(FavoriteRequest r,CancellationToken ct)=>Ok(await s.AddFavoriteAsync(r,ct));[HttpDelete("{id:guid}")]public async Task<IActionResult>Delete(Guid id,CancellationToken ct)=>await s.DeleteFavoriteAsync(id,ct)?NoContent():NotFound();}
[ApiController,Authorize,Route("api/recentes")]public sealed class RecentesController:ControllerBase{private readonly IProductivityService s;public RecentesController(IProductivityService s)=>this.s=s;[HttpGet]public async Task<IActionResult>Get(CancellationToken ct)=>Ok(await s.RecentAsync(ct));[HttpDelete]public async Task<IActionResult>Clear(CancellationToken ct)=>Ok(new{deleted=await s.ClearRecentAsync(null,ct)});[HttpDelete("{id:guid}")]public async Task<IActionResult>Delete(Guid id,CancellationToken ct)=>await s.ClearRecentAsync(id,ct)>0?NoContent():NotFound();}
